Definition re_shape (i k : nat) (cells : list kentry) : bool :=
  match i, k with
  | 0, 0 => has cells EOFCLR42
  | 2, 0 => has cells (KRange (EVar 63) 0 0) && has cells (KRange (EVar 70) 0 0) && has cells (KRange (EVar 62) 0 1)      (* [comment removed for export] *)
  | 3, 0 => has cells (KRange (EVar 66) 0 0) && has cells (KRange (SLTU1 (EVar 65) (EVar 64)) 1 1) && has cells EOFCLR42
  | 3, 2 => has cells (KRange (EVar 66) 0 0) && has cells (KRange (SLTU1 (EVar 65) (EVar 64)) 0 0)                         (* [comment removed for export] *)
  | 4, 0 => has cells (KRange (EVar 87) 0 0) && has cells (KRange (SLTU1 (EVar 86) (EVar 85)) 1 1) && has cells (KRange (EVar 62) 0 1)
  | 4, 2 => has cells (KRange (EVar 87) 0 0) && has cells (KRange (SLTU1 (EVar 86) (EVar 85)) 0 0)                         (* [comment removed for export] *)
  | _, _ => false
  end%nat%bool.
