Definition leaf_chk (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto _ _ => false
  | CC.TOther pc =>
      let cells := SR.ps_cells ps in
      (CH2.blocks_eqb (nth i G.BLS []) (BLK i) && CHA.foot_chk GT.NF G.HDECL c (BLK i) [] && CBA.regions_eqb (CC.cp_F c) CPF && Nat.eqb (CC.cp_nx c) (NX i) &&
      match CH2.ret_of G.RETS i k with
      | Some j =>
          match nth_error G.CPS j with
          | Some cj =>
              (CH2.blocks_eqb (nth j G.BLS []) (BLK j) &&
              if Z.eqb pc PC_RC then
                (Z.eqb (SR.ps_pc ps) PC_RC && Nat.eqb i 1 && Nat.eqb j 2
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 8304 5 (firstn 2 (BLK 1%nat)) [] WREGS_RC NEWS_RC (Some (EVar 60)) c ps cj (BLK 1%nat) [] (BLK 2%nat) [] with
                    | Some ci => Z.eqb (CH2.ci_csp ci) (-80) && Nat.eqb (CH2.ci_nx ci) 60 | None => false end
                 && CL.ps_reg_is ps 10 RE && CL.ps_reg_is ps 11 EE && has cells (WEQ 1%nat 1))%bool
              else if Z.eqb pc PC_PCD then
                (Z.eqb (SR.ps_pc ps) PC_PCD && ((Nat.eqb i 1 && Nat.eqb j 3) || (Nat.eqb i 2 && Nat.eqb j 4))
                 && match CHA.custom_chk GT.NF G.HDECL GT.SCELLS GT.GLO GT.GHI 9792 8 [(chE, ELit 16384)] [] WREGS_PCD (NEWS_PCD (GPCD i)) None c ps cj (BLK i) [] (BLK j) [] with
                    | Some ci => Z.eqb (CH2.ci_csp ci) (-80) && Nat.eqb (CH2.ci_nx ci) (GPCD i) | None => false end
                 && CL.ps_reg_is ps 10 PE && CL.ps_reg_is ps 11 EE
                 && (if Nat.eqb i 1 then has cells (WEQ 1%nat 0) && has cells (KWord (SA RE 512) 8 (EVar 40)) && has cells (KWord (SA RE 520) 8 (EVar 39))
                     else has cells (KWord (SA RE 520) 8 (EVar 60)) && has cells (KWord (SA RE 512) 8 (ADDE (EVar 60) (EVar 70))) && has cells (KRange (EVar 70) 1 18446744073709551615)
                          && has cells (KRange (EVar 63) 0 0)))%bool
              else false)%bool
          | None => false
          end
      | None =>
          if Z.eqb pc RETPC then (CBA.exit_base_chk GT.NF RETPC c ps && exit_shape i cells)%bool
          else if Z.eqb pc LOOPC then (Z.eqb (SR.ps_pc ps) LOOPC && expr_eqb (CC.cp_meas c) (MEASX i) && link_chk i cells && RNA.reentry_chk GT.NF c ps G.cp1 (mk_s i ps)
                                       && CHA.goto_amb_chk GT.NF G.HDECL c (BLK i) (BLK 1%nat) [] [] (mk_s i ps) && re_shape i k cells)%bool
          else if Z.eqb pc PC_PCD then (Nat.eqb i 0 && CRB.tail_base_chk GT.NF PC_PCD c ps && CL.ps_reg_is ps 10 PE && CL.ps_reg_is ps 11 EE && has cells EOFSET42
                                        && has cells (KWord (SA RE 512) 8 (EVar 40)) && has cells (KWord (SA RE 520) 8 (EVar 39)))%bool
else if Z.eqb pc DEADW then (Nat.eqb i 2 && has cells WRAPD && has cells (KRange (EVar 70) 1 18446744073709551615))%bool   (* [comment removed for export] *)
          else if Z.eqb pc PC_SETEC then (Nat.eqb i 0 && has cells BADODD42)%bool
          else false
      end)%bool
  end.
